  <script>
    const canvas = document.getElementById('pendulum-canvas');
    const ctx = canvas.getContext('2d');

    let pendulumLength = 200; // in pixels
    let initialAngle = 0;
    let angle = 0;
    let velocity = 0;
    let g = 0.981; // gravitational constant in pixels per second squared
    let dt = 0.01; // time step in seconds

    let isReleased = false;

    function drawPendulum() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.arc(canvas.width / 2, canvas.height / 2, pendulumLength, 0, 2 * Math.PI);
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(canvas.width / 2 + pendulumLength * Math.sin(angle), canvas.height / 2 - pendulumLength * Math.cos(angle), 10, 0, 2 * Math.PI);
      ctx.fill();

      ctx.font = "24px Arial";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillStyle = "black";
      ctx.fillText(Math.round(angle * 180 / Math.PI) + "°", canvas.width / 2, canvas.height / 2);
    }

    function updatePendulum() {
      if (isReleased) {
        velocity += g / pendulumLength * Math.sin(angle) * dt;
        angle += velocity * dt;
      }
    }

    function releasePendulum() {
