    setInterval(() => {
      updatePendulum();
      drawPendulum();
    }, 16); // 16ms = ~60fps

    document.getElementById('initial-angle').addEventListener('input', () => {
      initialAngle = parseInt(document.getElementById('initial-angle').value);
      angle = initialAngle * Math.PI / 180;
      velocity = 0;
    });
  </script>
</body>
</html>
