import pygame
import sys
import random
import time

# Directions
UP = 1
DOWN = 2
LEFT = 3
RIGHT = 4

class SnakeGame:
    def __init__(self, width=800, height=600):
        self.width, self.height = width, height
        self.snake = [(200, 100)]
        self.direction = RIGHT
        self.food = (random.randint(0, width-10), random.randint(0, height-10))
        self.speed = 10

    def draw(self, screen):
        screen.fill((0,0,0))
        for x, y in self.snake:
            pygame.draw.rect(screen, (0,255,0), (x, y, 10, 10))
        pygame.draw.rect(screen, (255,0,0), (self.food[0], self.food[1], 10, 10))
        pygame.display.flip()

    def update(self):
        if self.direction == RIGHT:
            self.snake.append((self.snake[-1][0] + 10, self.snake[-1][1]))
        elif self.direction == LEFT:
            self.snake.append((self.snake[-1][0] - 10, self.snake[-1][1]))
        elif self.direction == UP:
            self.snake.append((self.snake[-1][0], self.snake[-1][1] - 10))
        elif self.direction == DOWN:
            self.snake.append((self.snake[-1][0], self.snake[-1][1] + 10))

        if len(self.snake) > 1 and self.snake[-1] in self.snake[:-1]:
            print("Game Over")
            pygame.quit()
            sys.exit()

        if self.snake[-1] == self.food:
            self.food = (random.randint(0, self.width-10), random.randint(0, self.height-10))
        else:
            self.snake.pop(0)

        if self.snake[-1][0] < 0 or self.snake[-1][0] > self.width-10 or self.snake[-1][1] < 0 or self.snake[-1][1] > self.height-10:
            print("Game Over")
            pygame.quit()
            sys.exit()

    def handle_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_UP:
                    if self.direction != DOWN:
                        self.direction = UP
                elif event.key == pygame.K_DOWN:
                    if self.direction != UP:
                        self.direction = DOWN
                elif event.key == pygame.K_LEFT:
                    if self.direction != RIGHT:
                        self.direction = LEFT
                elif event.key == pygame.K_RIGHT:
                    if self.direction != LEFT:
                        self.direction = RIGHT

    def run(self):
        pygame.init()
        screen = pygame.display.set_mode((self.width, self.height))
        clock = pygame.time.Clock()
        while True:
            self.update()
            self.draw(screen)
            self.handle_events()
            clock.tick(self.speed)

if __name__ == "__main__":
    game = SnakeGame()
    game.run()
