#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  gpioInitialise();

  // Set pin 12 as an output
  gpioSetup(12, PI_OUTPUT);

  while (1) {
    // Set pin 12 high (on)
    gpioWrite(12, PI_HIGH);
    delay(1000); // wait 1 second

    // Set pin 12 low (off)
    gpioWrite(12, PI_LOW);
    delay(1000); // wait 1 second
  }

  // Clean up
  gpioTerminate();
  return 0;
}
```
