  return (
    <Component {...pageProps} />
  );
}

MyApp.getInitialProps = async () => {
  // This method gets called at the server-side
  // before returning the initial HTML
  return {};
};

const barVisibilityConditions = [
  '!/404', // Ignore 404 page
];
const Ball = () => {
  return <div>Conditional navbar</div>;
};

function getComponentAndProps(route) {
  if (barVisibilityConditions.includes(route) || route.includes('/404')) {
    return [null, {}];
  }
  return [Ball, {}];
}

function MyAppWrapper({ Component, pageProps }) {
  const [navbarComponent, navbarProps] = getComponentAndProps(window.location.pathname);
  return (
    <>
      {navbarComponent && <navbarComponent {...navbarProps} />}
      <Component {...pageProps} />
    </>
  );
}

export default enforce(MyAppWrapper, MyApp);
```

